style.css:
@-moz-document domain("roblox.com") {
/* Reze's Midnight — Roblox */

:root {
  --my-bg: #0b0a10;
  --my-panel: #15131b;
  --my-panel-hover: #201b28;
  --my-purple: #987b9f;
  --my-purple-soft: #76617f;
  --my-purple-glow: rgba(152, 123, 159, 0.14);
  --my-text: #eeeaf0;
  --my-muted: #a39aa8;
}

html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

a {
  color: var(--my-purple) !important;
}

a:hover {
  color: #c0a8c8 !important;
}

img {
  border-radius: 10px !important;
}

button,
[role="button"] {
  border-radius: 9px !important;
  transition: all 0.2s ease !important;
}

button:hover,
[role="button"]:hover {
  box-shadow: 0 0 12px var(--my-purple-glow) !important;
}

* {
  scrollbar-color: var(--my-purple-soft) var(--my-bg) !important;
}
}
